/* ===== V27.1 · Módulo GIMNASIO (perfil `gym` = SVBDemoGimnasios) y ENTRENADOR PERSONAL (perfil `nc` = MovimientoInteligenteNC) =====
   Capa de rubro sobre la base genérica de un solo dueño (raveV2): los socios/alumnos SON clientes del Club, la cuota se cobra en
   Vender (caja, comprobante, ARCA y reportes de siempre) y al cobrarse extiende la membresía. Pantallas agrupadas en pestañas:
   Gimnasio › Acceso · Socios · Membresías · Clases · Rutinas · Máquinas  (nc: Entrenamiento › Alumnos · Agenda · Programas · Planes · Asistencia · Equipamiento).
   Reglas Sistema VB: nada se simula como cobro real; la huella queda pendiente de dispositivo y revisión legal (dato biométrico);
   WhatsApp asistido (wa.me, lo envía una persona); auditoría encadenada en cada acción que toca dinero o permisos. */
function GYM_PROF(){return (typeof window!=='undefined'&&window.RAVE_BUILD&&window.RAVE_BUILD.profile)||'';}
function isGymBuild(){const p=GYM_PROF();return p==='gym'||p==='nc';}
const isNC=()=>GYM_PROF()==='nc';
const GW=()=>isNC()?{s:'alumno',ss:'alumnos',S:'Alumno',SS:'Alumnos',g:'Entrenamiento',m:'plan',M:'Plan',MM:'Planes'}:{s:'socio',ss:'socios',S:'Socio',SS:'Socios',g:'Gimnasio',m:'membresía',M:'Membresía',MM:'Membresías'};
const gT=()=>dkey(now());
const gDiff=(a,b)=>Math.round((new Date(b+'T12:00:00Z')-new Date(a+'T12:00:00Z'))/864e5);
function gAddM(k,n){const [y,m,d]=k.split('-').map(Number);const t=new Date(Date.UTC(y,m-1+n,1,12));const last=new Date(Date.UTC(t.getUTCFullYear(),t.getUTCMonth()+1,0,12)).getUTCDate();t.setUTCDate(Math.min(d,last));return t.toISOString().slice(0,10);}
const gWeekStart=k=>{const w=dowOfKey(k);return addDays(k,-((w+6)%7));};
const gB64=o=>{const s=btoa(unescape(encodeURIComponent(JSON.stringify(o))));return s.replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
const GDAYS=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const GEXCAT={legs:'Piernas',hinge:'Glúteos e isquios',push:'Pecho y empuje',pull:'Espalda y tracción',shoulders:'Hombros',arms:'Brazos',core:'Zona media',cardio:'Cardio y HIIT'};
const GINJ={rodilla:'Rodilla',lumbar:'Zona lumbar',hombro:'Hombro'};
const GGOALS={fuerza:'Ganar fuerza',hipertrofia:'Ganar masa muscular',grasa:'Bajar grasa',salud:'Salud y bienestar',rendimiento:'Rendimiento deportivo'};
const GLEVELS={principiante:'Principiante',intermedio:'Intermedio',avanzado:'Avanzado'};
const GMEAS=[['peso','Peso','kg'],['grasa','Grasa corporal','%'],['cintura','Cintura','cm'],['cadera','Cadera','cm'],['pecho','Pecho','cm'],['brazo','Brazo','cm'],['pierna','Pierna','cm']];
const GMETH={qr:'QR',nfc:'NFC',dni:'Documento',manual:'Manual',sesion:'Sesión',clase:'Clase',salida:'Salida'};
const gYt=n=>'https://www.youtube.com/results?search_query='+encodeURIComponent(n+' técnica correcta');
/* V27.4 · los videos se ven dentro del sistema (reproductor embebido), nunca se sale a otra página */
const gYtId=u=>{const m=String(u||'').match(/^https:\/\/(?:www\.|m\.)?(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/|live\/)|youtu\.be\/)([\w-]{11})/i);return m?m[1]:'';};
const gYtOk=u=>!u||!!gYtId(u);
function gPlayer(id){return `<div style="position:relative;padding-top:56.25%;border-radius:14px;overflow:hidden;background:#000"><iframe src="https://www.youtube-nocookie.com/embed/${id}?rel=0&modestbranding=1&playsinline=1" title="Video del ejercicio" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" style="position:absolute;inset:0;width:100%;height:100%;border:0"></iframe></div>`;}
A.gVideo=el=>{const k=el.dataset.k,id=el.dataset.id,o=k==='mq'?gMq(id):gEx(id);if(!o)return;const v=gYtId(o.video),ed=can('gym_admin')||can('gym_train');
 const tip=k==='mq'?(o.notes||''):(o.tip||'');
 modal((k==='mq'?'Cómo usar: ':'Técnica: ')+o.name,(v?gPlayer(v):`<div class="card" style="text-align:center;padding:1.2rem"><p style="margin:.2rem 0"><b>Todavía no hay video cargado para este ${k==='mq'?'equipo':'ejercicio'}.</b></p><p class="sm mut" style="margin:0">Pegá abajo el enlace de YouTube y queda guardado: se reproduce acá mismo y en la app del ${GW().s}.</p></div>`)+
 (tip?`<p style="margin:.8rem 0 0"><b>Indicación:</b> ${esc(tip)}</p>`:'')+
 (ed?`<label for="gv-u" style="margin-top:.8rem">Enlace de YouTube</label><input id="gv-u" value="${esc(o.video||'')}" placeholder="https://www.youtube.com/watch?v=…">`:''),
 ed?{okText:'Guardar video',cancelText:'Cerrar',onOk:w=>{const u=val('gv-u').trim();if(!gYtOk(u))return w._err('Tiene que ser un enlace de un video de YouTube (youtube.com/watch?v=… o youtu.be/…).'),false;o.video=u;audit(k==='mq'?'GYM_EQUIPO_VIDEO':'GYM_EJERCICIO_VIDEO',o.name);save();toast(u?'Video guardado.':'Video quitado.');rerender();}}:{ok:false,cancelText:'Cerrar'});};

