/* ---------- socios / alumnos ---------- */
let gF={q:'',f:'activos',plan:'',pg:0};
function gFilter(){const t=gT(),g=+G().cfg.grace||0,sg=gSegments();let L=gMembers();const q=gF.q.trim().toLowerCase();
 if(q)L=L.filter(c=>gName(c).toLowerCase().includes(q)||(c.dni||'').includes(q)||(c.wa||'').includes(q)||gCode(c).toLowerCase().includes(q));
 if(gF.plan)L=L.filter(c=>gm(c.id).plan===gF.plan);
 const f=gF.f,ids=a=>new Set(a.map(c=>c.id));
 if(f==='activos')L=L.filter(gActive);else if(f==='aldia')L=L.filter(c=>gActive(c)&&gm(c.id).due>=t);else if(f==='porvencer'){const s=ids(sg.venc);L=L.filter(c=>s.has(c.id));}
 else if(f==='gracia')L=L.filter(c=>gActive(c)&&!gm(c.id).nuevo&&gm(c.id).due<t&&gDiff(gm(c.id).due,t)<=g);else if(f==='vencidas'){const s=ids(sg.vencida);L=L.filter(c=>s.has(c.id));}
 else if(f==='congeladas'){const s=ids(sg.congel);L=L.filter(c=>s.has(c.id));}else if(f==='riesgo'){const s=ids(sg.riesgo);L=L.filter(c=>s.has(c.id));}
 else if(f==='sinrutina')L=L.filter(c=>gActive(c)&&!gRoutineOf(c.id));else if(f==='sindecl')L=L.filter(c=>gActive(c)&&!gm(c.id).decl);else if(f==='baja')L=L.filter(c=>!gActive(c));
 return L.sort((a,b)=>gName(a).localeCompare(gName(b),'es'));}
function gKpis(){const t=gT(),A=gActives(),okN=A.filter(c=>gm(c.id).due>=t).length,sg=gSegments(),ms=t.slice(0,8)+'01';
 const due7=A.filter(c=>{const m=gm(c.id);return !gFrozen(m)&&m.due>=t&&m.due<=addDays(t,7);}),due7s=due7.reduce((a,c)=>a+gPrice(gPlanOf(gm(c.id))),0);
 const cuotas=(G().pays||[]).filter(p=>dkey(p.ts)>=ms).reduce((a,p)=>a+p.amt,0);const mrr=A.reduce((a,c)=>a+gPrice(gPlanOf(gm(c.id))),0);
 const K=(l,v,f,act)=>`<div class="card kpi"${act?` data-act="gGoF" data-f="${act}" role="button" tabindex="0" style="cursor:pointer"`:''}><span>${l}</span><b>${v}</b><span>${f}</span></div>`;
 return`<div class="grid g4">${K(GW().SS+' activos',A.length,gMembers().filter(c=>gm(c.id).created>=ms).length+' altas este mes · '+sg.congel.length+(isNC()?' congelado(s)':' congelada(s)'),'activos')}${K('Cuotas al día',okN+' de '+A.length,(A.length?Math.round((A.length-okN)/A.length*100):0)+' % de mora ('+(A.length-okN)+' ÷ '+A.length+')','vencidas')}${K('A cobrar en 7 días',money(due7s),due7.length+' cuota(s) vencen hasta el '+dmy(addDays(t,7)),'porvencer')}${K('Cuotas cobradas en el mes',money(cuotas),'Ingreso mensual esperado '+money(mrr),'')}${K('Riesgo de abandono',sg.riesgo.length,'Al día pero sin venir hace 14 días o más','riesgo')}${K('Rutinas asignadas',new Set(G().routines.map(r=>r.cust)).size,'de '+A.length+' '+GW().ss+' activos','sinrutina')}${isNC()?'':K('Adentro ahora',gInside().length+(G().cfg.capacity?' de '+G().cfg.capacity:''),'según accesos de las últimas 3 horas','')}${K('Asistencias hoy',G().att.filter(a=>a.date===t).length,'una por persona y día','')}</div>`;}
A.gGoF=el=>{gF.f=el.dataset.f;gF.pg=0;go('gsocios');rerender();};
reg('gsocios',isNC()?'Alumnos':'Socios','users','gym',()=>{const L=gFilter(),pg=40,pages=Math.max(1,Math.ceil(L.length/pg));if(gF.pg>=pages)gF.pg=pages-1;const P=L.slice(gF.pg*pg,gF.pg*pg+pg);
 const FL=[['activos','Activos'],['aldia','Al día'],['porvencer','Por vencer'],['gracia','En período de gracia'],['vencidas','Vencidas'],['congeladas','Congeladas'],['riesgo','En riesgo de abandono'],['sinrutina','Sin rutina'],['sindecl','Sin declaración de salud'],['baja','Bajas'],['todos','Todos']];
 return`<div class="row"><h1 class="sp">${GW().SS}</h1>${expBarG()}<button class="btn gold" data-act="gNew">+ ${GW().S}</button></div>${gKpis()}
 <div class="card" style="margin-top:1rem"><div class="row"><div class="sp"><label for="gs-q">Buscar por nombre, documento, WhatsApp o código</label><input id="gs-q" value="${esc(gF.q)}" autocomplete="off" placeholder="Ej: Lucía, 33123456"></div>
 <div><label for="gs-f">Mostrar</label><select id="gs-f">${FL.map(([k,l])=>`<option value="${k}" ${gF.f===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="gs-p">${GW().M}</label><select id="gs-p"><option value="">${isNC()?'Todos':'Todas'}</option>${G().plans.map(p=>`<option value="${p.id}" ${gF.plan===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div>
 <p class="sm mut">${L.length} resultado(s)</p><div class="tw"><table><thead><tr><th>${GW().S}</th><th>${GW().M}</th><th>Paga hasta</th><th>Estado</th><th class="r">Acciones</th></tr></thead><tbody>${P.map(c=>{const m=gm(c.id),pl=gPlanOf(m),st=gStatus(c);
  return`<tr><td><b>${esc(gName(c))}</b>${c.origin==='ejemplo'?' <span class="tag sim">ejemplo</span>':''}<div class="sm mut">${gCode(c)} · DNI ${esc(c.dni||'—')}${m.mode==='virtual'?' · virtual':''}</div></td><td>${esc(pl?pl.name:'—')}</td><td>${dmy(m.due)}</td><td>${gTag(st)}${m.decl?'':' <span class="tag warn">sin declaración</span>'}</td>
  <td class="r"><button class="btn sm" data-act="gFicha" data-id="${c.id}">Ficha</button>${st.k==='ok'||st.k==='mute'?'':`<button class="btn sm gold" data-act="gPay" data-id="${c.id}">Cobrar</button>`}${st.k==='bad'?gWaBtn(c,'vencida','WhatsApp'):st.k==='warn'?gWaBtn(c,'venc','WhatsApp'):''}</td></tr>`;}).join('')||`<tr><td colspan="5" class="mut">No hay ${GW().ss} con este filtro.</td></tr>`}</tbody></table></div>
 ${pages>1?`<div class="row"><button class="btn sm" data-act="gPg" data-d="-1" ${gF.pg?'':'disabled'}>Anterior</button><span class="sp sm mut" style="text-align:center">Página ${gF.pg+1} de ${pages}</span><button class="btn sm" data-act="gPg" data-d="1" ${gF.pg<pages-1?'':'disabled'}>Siguiente</button></div>`:''}</div>
 ${gCampaignCard()}`;},()=>{const q=$('#gs-q');if(q){q.addEventListener('input',()=>{gF.q=q.value;gF.pg=0;clearTimeout(gF.t);gF.t=setTimeout(()=>{rerender();setTimeout(()=>{const n=$('#gs-q');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}},0);},250);});}
 ['gs-f','gs-p'].forEach(id=>{const e=$('#'+id);e&&e.addEventListener('change',()=>{gF.f=val('gs-f');gF.plan=val('gs-p');gF.pg=0;rerender();});});},'Gimnasio');
A.gPg=el=>{gF.pg=Math.max(0,gF.pg+(+el.dataset.d));rerender();};
function expBarG(){return can('impex')?`<button class="btn sm" data-act="gCsv">Exportar CSV</button>`:'';}
A.gCsv=()=>{const rows=gMembers().map(c=>{const m=gm(c.id),pl=gPlanOf(m);return[gCode(c),gName(c),c.dni||'',c.wa||'',pl?pl.name:'',m.due,gStatus(c).t,GGOALS[m.goal]||'',GLEVELS[m.level]||'',gMonthAtt(c.id),m.decl?'sí':'no'];});
 download(GW().ss+'-'+gT()+'.csv',toCSV(['Código',GW().S,'Documento','WhatsApp',GW().M,'Paga hasta','Estado','Objetivo','Nivel','Asistencias del mes','Declaración de salud'],rows),'text/csv');audit('EXPORTAR',GW().ss+' (CSV)');};
function gCampaignCard(){const sg=gSegments();const K=[['venc','Vencen en los próximos días',sg.venc],['vencida','Cuotas vencidas',sg.vencida],['riesgo','Riesgo de abandono',sg.riesgo],['cumple','Cumplen años hoy',sg.cumple]];
 return`<div class="card" style="margin-top:1rem"><h3>Avisos por WhatsApp</h3><p class="sm mut">Envío asistido uno por uno: el mensaje se abre listo en WhatsApp y lo manda una persona. Sólo ${GW().ss} con consentimiento de comunicaciones.</p><div class="grid g4">${K.map(([k,l,L])=>`<div class="card kpi"><span>${l}</span><b>${L.length}</b><button class="btn sm" data-act="gQueue" data-k="${k}" ${L.length?'':'disabled'}>Preparar envíos</button></div>`).join('')}</div></div>`;}
A.gQueue=el=>{const k=el.dataset.k,L=gSegments()[k==='venc'?'venc':k==='vencida'?'vencida':k==='riesgo'?'riesgo':'cumple'];const ok=L.filter(c=>c.consent&&c.consent.comm!==false&&waDigits(c));
 modal('Avisos por WhatsApp',`<p class="sm mut">${ok.length} listo(s)${L.length-ok.length?' · '+(L.length-ok.length)+' sin consentimiento o sin teléfono':''}. Tocá cada uno: se abre WhatsApp con el texto.</p><div class="tw"><table><tbody>${ok.slice(0,60).map(c=>`<tr><td>${esc(gName(c))}<div class="sm mut">${esc(gStatus(c).t)}</div></td><td class="r">${gWaBtn(c,k,'WhatsApp','gold')}</td></tr>`).join('')||'<tr><td class="mut">Nadie para avisar.</td></tr>'}</tbody></table></div>`,{ok:false,cancelText:'Cerrar',wide:true});};

/* alta y edición */
A.gNew=()=>gEdit(null);A.gEditM=el=>{$$('#modal-root .ov').forEach(o=>o.remove());gEdit(gCust(el.dataset.id));};
function gEdit(c){const m=c?gm(c.id):null;const P=G().plans,trs=S.employees.filter(e=>e.active);
 modal(c?'Editar '+GW().s:'Nuevo '+GW().s,`<div class="grid g2"><div><label for="ge-n">Nombre</label><input id="ge-n" maxlength="40" value="${esc(c?c.name:'')}"></div><div><label for="ge-l">Apellido</label><input id="ge-l" maxlength="40" value="${esc(c?c.last:'')}"></div>
 <div><label for="ge-d">Documento</label><input id="ge-d" inputmode="numeric" value="${esc(c?c.dni:'')}" placeholder="Sin puntos"></div><div><label for="ge-w">WhatsApp</label><input id="ge-w" inputmode="tel" value="${esc(c?String(c.wa||'').replace(/^\+549/,''):'')}" placeholder="Ej: 3875551234"></div>
 <div><label for="ge-b">Fecha de nacimiento</label><input id="ge-b" type="date" value="${esc(c?c.birth:'')}"></div><div><label for="ge-p">${GW().M}</label><select id="ge-p">${P.map(p=>`<option value="${p.id}" ${m&&m.plan===p.id?'selected':''}>${esc(p.name)} · ${money(gPrice(p))}</option>`).join('')}</select></div>
 <div><label for="ge-g">Objetivo</label><select id="ge-g">${Object.entries(GGOALS).map(([k,l])=>`<option value="${k}" ${m&&m.goal===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="ge-v">Nivel</label><select id="ge-v">${Object.entries(GLEVELS).map(([k,l])=>`<option value="${k}" ${m&&m.level===k?'selected':''}>${l}</option>`).join('')}</select></div>
 ${isNC()?`<div><label for="ge-mo">Modalidad</label><select id="ge-mo"><option value="presencial">Presencial</option><option value="virtual" ${m&&m.mode==='virtual'?'selected':''}>Programación virtual</option></select></div>`:`<div><label for="ge-nfc">Código de tarjeta NFC</label><input id="ge-nfc" value="${esc(m?m.nfc:'')}" placeholder="Opcional"></div>`}
 <div><label for="ge-t">Profesor a cargo</label><select id="ge-t"><option value="">Sin asignar</option>${trs.map(e=>`<option value="${e.id}" ${m&&m.trainer===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div></div>
 <fieldset style="border:0;padding:0;margin:.6rem 0 0"><legend class="sm mut">Lesiones a cuidar (el entrenador inteligente las respeta)</legend><div class="row">${Object.entries(GINJ).map(([k,l])=>`<label class="chk"><input type="checkbox" class="ge-i" value="${k}" ${m&&(m.inj||[]).includes(k)?'checked':''}> ${l}</label>`).join('')}</div></fieldset>
 <label for="ge-h">Salud y observaciones</label><textarea id="ge-h" maxlength="300">${esc(m?m.health:'')}</textarea>
 <label class="chk"><input type="checkbox" id="ge-dc" ${m&&m.decl?'checked':''}> Entregó la declaración de salud (apto físico)</label><label class="chk"><input type="checkbox" id="ge-cm" ${!c||!c.consent||c.consent.comm!==false?'checked':''}> Acepta recibir avisos por WhatsApp</label>
 ${c?'':`<p class="sm mut">Queda «Pendiente de primer pago»: al cobrar la primera cuota en Vender se activa.</p>`}`,
 {wide:true,okText:'Guardar',onOk:w=>{const n=val('ge-n').trim(),l=val('ge-l').trim(),d=normDni(val('ge-d')),wa=normWA(val('ge-w'));if(n.length<2)return w._err('Falta el nombre.'),false;
  if(d&&!dniOk(d))return w._err('El documento debe tener 7 u 8 números.'),false;if(d&&S.customers.some(x=>x.dni===d&&(!c||x.id!==c.id)))return w._err('Ya hay un cliente con ese documento.'),false;
  const inj=$$('.ge-i',w).filter(x=>x.checked).map(x=>x.value);const comm=$('#ge-cm',w).checked;let cc=c;
  if(!cc){cc=custCreate({name:n,last:l,birth:val('ge-b'),wa,dni:d,club:true,comm},'mostrador');}else{cc.name=n;cc.last=l;cc.birth=val('ge-b')||'';if(wa)cc.wa=waFull(wa);if(d)cc.dni=d;cc.consent=Object.assign({},cc.consent||{},{comm});}
  const t=gT();let mm=gm(cc.id);const was=mm?mm.plan:'';if(!mm)mm=G().m[cc.id]={due:addDays(t,-1),nuevo:true,measures:[],created:t,freeze:null};
  Object.assign(mm,{plan:val('ge-p'),goal:val('ge-g'),level:val('ge-v'),trainer:val('ge-t'),inj,health:val('ge-h').trim(),decl:$('#ge-dc',w).checked,mode:isNC()?val('ge-mo'):(mm.mode||'presencial'),nfc:isNC()?(mm.nfc||''):val('ge-nfc').trim().toUpperCase()});
  audit(c?(was!==mm.plan?'GYM_CAMBIO_PLAN':'GYM_FICHA'):'GYM_ALTA',gName(cc)+' · '+(gPlanOf(mm)||{}).name);save();rerender();setTimeout(()=>gFichaOpen(cc.id),40);
  toast(c?'Datos guardados':GW().S+' agregado. Cobrá la primera cuota y enviale su app.');}});}

/* ficha con pestañas */
let gFt='res';
A.gFicha=el=>{gFt='res';gFichaOpen(el.dataset.id);};
A.gFTab=el=>{gFt=el.dataset.t;gFichaOpen(el.dataset.id);};
function gLine(L,key,unit){const P=L.filter(x=>x[key]!=null&&x[key]!=='').map(x=>({d:x.date,v:+x[key]}));if(P.length<2)return'';const W=520,H=150,pl=34,pr=14,pt=22,pb=24,mn=Math.min(...P.map(p=>p.v)),mx=Math.max(...P.map(p=>p.v)),rg=(mx-mn)||1;
 const X=i=>pl+i*(W-pl-pr)/(P.length-1),Y=v=>pt+(1-(v-mn)/rg)*(H-pt-pb);
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Evolución de ${esc(key)}" style="max-width:100%"><line x1="${pl}" x2="${W-pr}" y1="${H-pb}" y2="${H-pb}" stroke="currentColor" stroke-opacity=".2"/><polyline fill="none" stroke="var(--gold)" stroke-width="2.5" points="${P.map((p,i)=>X(i).toFixed(1)+','+Y(p.v).toFixed(1)).join(' ')}"/>${P.map((p,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(p.v).toFixed(1)}" r="4" fill="var(--gold)"/><text x="${X(i).toFixed(1)}" y="${(Y(p.v)-8).toFixed(1)}" text-anchor="middle" font-size="11" fill="currentColor">${String(p.v).replace('.',',')}</text><text x="${X(i).toFixed(1)}" y="${H-7}" text-anchor="middle" font-size="10" fill="currentColor" fill-opacity=".6">${dmy(p.d).slice(0,-3)}</text>`).join('')}<text x="2" y="14" font-size="10" fill="currentColor" fill-opacity=".6">${unit}</text></svg>`;}
function gRtTable(r){return r.days.map(d=>`<h4 style="margin:.8rem 0 .3rem">${esc(d.n)}</h4><div class="tw"><table><thead><tr><th>Ejercicio</th><th>Series × reps</th><th class="r">Carga</th><th class="r">Descanso</th><th></th></tr></thead><tbody>${d.items.map(it=>{const e=gEx(it.ex);if(!e)return'';const q=e.mach.map(gMq).filter(Boolean);
 return`<tr><td><b>${esc(e.name)}</b><div class="sm mut">${esc(GEXCAT[e.cat])}${q.length?' · '+esc(q[0].name):''}</div></td><td>${it.s} × ${esc(it.r)}</td><td class="r">${it.kg?esc(it.kg)+' kg':'<span class="mut">a definir</span>'}</td><td class="r">${it.rest?it.rest+' s':'—'}</td><td class="r"><button class="btn sm" data-act="gVideo" data-k="ex" data-id="${e.id}">${gYtId(e.video)?'▶ Video':'Video'}</button></td></tr>`;}).join('')}</tbody></table></div>`).join('');}
A.gOpenUrl=el=>openExternal(el.dataset.u);
function gRtText(r){const c=gCust(r.cust);return'*'+S.tenant.name+'* · '+gName(c)+'\n'+r.name+'\n'+r.days.map(d=>'\n*'+d.n+'*\n'+d.items.map(it=>{const e=gEx(it.ex);return'• '+(e?e.name:'')+': '+it.s+'×'+it.r+(it.kg?' · '+it.kg+' kg':'')+(it.rest?' · descanso '+it.rest+' s':'');}).join('\n')).join('\n')+'\n\nVideos y temporizador de descanso en tu app.';}
function gFichaOpen(cid){$$('#modal-root .ov').forEach(o=>o.remove());const c=gCust(cid);if(!c)return;const m=gm(c.id)||{},st=gStatus(c),pl=gPlanOf(m),t=gT(),tr=S.employees.find(e=>e.id===m.trainer);
 const tabs=[['res','Resumen'],['prog','Progreso'],['rt',isNC()?'Programa':'Rutina'],['hist','Historial']];let body='';
 if(gFt==='res'){body=`<div class="grid g2" style="align-items:center"><div><div class="row"><b style="font:700 1.2rem Georgia,serif">${esc(pl?pl.name:'Sin '+GW().m)}</b>${gTag(st)}</div>
  <p class="sm">Paga hasta <b>${dmy(m.due)}</b> · ${gMonthAtt(c.id)} asistencia(s) este mes · racha de ${gStreak(c.id)} semana(s)${m.mode==='virtual'?' · modalidad virtual':''}</p>
  <p class="sm">Objetivo: ${esc(GGOALS[m.goal]||'—')} · Nivel: ${esc(GLEVELS[m.level]||'—')}${tr?' · Profesor: '+esc(tr.name):''}</p>
  <p class="sm">Documento ${esc(c.dni||'—')} · WhatsApp ${esc(c.wa||'—')}${m.nfc?' · NFC '+esc(m.nfc):''}</p>
  ${m.health||(m.inj||[]).length?`<p class="sm"><b>Salud:</b> ${esc(m.health||'')}${(m.inj||[]).length?' · cuidar '+m.inj.map(i=>GINJ[i].toLowerCase()).join(', '):''}</p>`:''}${m.decl?'':'<p><span class="tag warn">Falta la declaración de salud</span></p>'}
  ${gFrozen(m)?`<p class="sm"><span class="tag">Congelada del ${dmy(m.freeze.from)} al ${dmy(m.freeze.until)}</span> ${esc(m.freeze.reason||'')}. El vencimiento ya se corrió esos días.</p>`:''}</div>
  <div style="text-align:center"><div style="width:150px;height:150px;margin:0 auto;background:#fff;border-radius:10px;padding:6px">${QR.svg(gCode(c),4,1)}</div><b style="letter-spacing:.1em">${gCode(c)}</b><div class="sm mut">Credencial de acceso</div></div></div>
  <div class="row" style="margin-top:.6rem"><button class="btn gold" data-act="gPay" data-id="${c.id}">Cobrar cuota</button><button class="btn" data-act="gEditM" data-id="${c.id}">Editar</button>${gActive(c)&&!gFrozen(m)&&m.due>=t?`<button class="btn" data-act="gFreeze" data-id="${c.id}">Congelar</button>`:''}${gFrozen(m)?`<button class="btn" data-act="gUnfreeze" data-id="${c.id}">Descongelar</button>`:''}${isAdm()?`<button class="btn" data-act="gFixDue" data-id="${c.id}">Corregir vencimiento</button>`:''}<button class="btn" data-act="gBaja" data-id="${c.id}">${gActive(c)?'Dar de baja':'Reactivar'}</button></div>
  <h4 style="margin:1rem 0 .3rem">App del ${GW().s}</h4><p class="sm mut">QR de acceso, estado de la cuota, rutina con videos y temporizador, progreso y ${isNC()?'agenda de sesiones':'clases'}. Se actualiza cada vez que se envía el enlace.</p>
  <div class="row"><button class="btn" data-act="gOpenUrl" data-u="${esc(gAppLink(c))}">Ver su app</button>${gWaBtn(c,'app','Enviar la app por WhatsApp','gold')}<button class="btn" data-act="gCopyApp" data-id="${c.id}">Copiar enlace</button></div>`;}
 else if(gFt==='prog'){const L=(m.measures||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)),f=L[0],l=L[L.length-1];const wk=[];for(let i=7;i>=0;i--){const a=addDays(gWeekStart(t),-7*i);wk.push([a,gAttOf(c.id).filter(x=>x.date>=a&&x.date<=addDays(a,6)).length]);}const mx=Math.max(1,...wk.map(x=>x[1]));
  body=`<div class="grid g4"><div class="card kpi"><span>Racha</span><b>${gStreak(c.id)}</b><span>semanas con 2 o más días</span></div><div class="card kpi"><span>Este mes</span><b>${gMonthAtt(c.id)}</b><span>asistencias</span></div><div class="card kpi"><span>Total</span><b>${gAttOf(c.id).length}</b><span>asistencias registradas</span></div></div>
  <h4 style="margin:.8rem 0 .3rem">Asistencias por semana</h4><div class="g-bars">${wk.map(([a,n])=>`<div><i style="height:${Math.round(n/mx*100)}%"></i><b>${n}</b><span>${dmy(a).slice(0,-3)}</span></div>`).join('')}</div>
  ${L.length?`<h4 style="margin:.8rem 0 .3rem">Peso</h4>${gLine(L,'peso','kg')}${L.some(x=>x.grasa)?`<h4 style="margin:.8rem 0 .3rem">Grasa corporal</h4>${gLine(L,'grasa','%')}`:''}
  <div class="tw"><table><thead><tr><th>Medida</th>${L.slice(-4).map(x=>`<th class="r">${dmy(x.date)}</th>`).join('')}<th class="r">Cambio</th></tr></thead><tbody>${GMEAS.map(([k,lb,u])=>{const d=f&&l&&f[k]!=null&&l[k]!=null?+(l[k]-f[k]).toFixed(1):null;return`<tr><td>${lb}</td>${L.slice(-4).map(x=>`<td class="r">${x[k]!=null?String(x[k]).replace('.',',')+' '+u:'—'}</td>`).join('')}<td class="r">${d==null?'—':(d>0?'+':'')+String(d).replace('.',',')+' '+u}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="mut">Todavía no hay mediciones.</p>'}
  <h4 style="margin:.8rem 0 .3rem">Cargar medición</h4><div class="grid g4"><div><label for="gm-date">Fecha</label><input id="gm-date" type="date" value="${t}"></div>${GMEAS.map(([k,lb,u])=>`<div><label for="gm-${k}">${lb} (${u})</label><input id="gm-${k}" inputmode="decimal" placeholder="${l&&l[k]!=null?String(l[k]).replace('.',','):''}"></div>`).join('')}</div><button class="btn gold" data-act="gMeasure" data-id="${c.id}" style="margin-top:.5rem">Guardar medición</button>`;}
 else if(gFt==='rt'){const r=gRoutineOf(c.id);body=r?`<div class="row"><div class="sp"><b>${esc(r.name)}</b><div class="sm mut">${esc(GLEVELS[r.level]||'')} · ${dmy(r.created)} · ${esc(r.by||'')}</div></div><button class="btn sm" data-act="gRtEdit" data-id="${r.id}">Editar cargas</button>${gWaBtn(c,'rutina','Enviar por WhatsApp')}<button class="btn sm gold" data-act="gRtFor" data-id="${c.id}">Armar otra</button></div>${r.notes&&r.notes.length?`<ul class="sm mut">${r.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}${gRtTable(r)}`
  :`<p class="mut">No tiene ${isNC()?'programa':'rutina'} asignada.</p><button class="btn gold" data-act="gRtFor" data-id="${c.id}">Armar con el entrenador inteligente</button>`;}
 else{const P=(G().pays||[]).filter(p=>p.cust===c.id).sort((a,b)=>b.ts-a.ts).slice(0,10),Ac=G().acc.filter(a=>a.cust===c.id).sort((a,b)=>b.ts-a.ts).slice(0,10);
  body=`<h4>Cuotas cobradas</h4>${P.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Venta</th><th>${GW().M}</th><th>Vencimiento</th><th class="r">Importe</th></tr></thead><tbody>${P.map(p=>`<tr><td>${fmtDT(p.ts)}</td><td>${esc(p.saleN)}</td><td>${esc((gPlan(p.plan)||{}).name||'')}</td><td>${dmy(p.prev)} → ${dmy(p.until)}</td><td class="r">${money(p.amt)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="mut sm">Sin cuotas cobradas en el sistema.</p>'}
  <h4>Accesos</h4>${Ac.length?`<div class="tw"><table><tbody>${Ac.map(a=>`<tr><td>${fmtDT(a.ts)}</td><td>${GMETH[a.method]||a.method}</td><td>${a.type==='out'?'Salida':a.res==='ok'?'Autorizado':a.res==='warn'?'Con aviso':'Denegado'}${a.why?' · '+esc(a.why):''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="mut sm">Sin accesos.</p>'}<p class="sm mut">Las compras, el monedero y los sellos del Club están en Clientes y Club.</p>`;}
 modal(gName(c),`<div class="row" role="tablist" aria-label="Secciones de la ficha">${tabs.map(([k,l])=>`<button class="btn sm ${gFt===k?'on':''}" role="tab" aria-selected="${gFt===k}" data-act="gFTab" data-t="${k}" data-id="${c.id}">${l}</button>`).join('')}</div><div style="margin-top:.8rem">${body}</div>`,{ok:false,cancelText:'Cerrar',wide:true});}
A.gCopyApp=async el=>{const c=gCust(el.dataset.id);if(!c)return;try{await navigator.clipboard.writeText(gAppLink(c));toast('Enlace de la app copiado');}catch(e){toast('No se pudo copiar: abrí «Ver su app» y copiá la dirección.',1);}};
A.gMeasure=el=>{const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!c||!m)return;const o={date:val('gm-date')||gT()};let any=false;GMEAS.forEach(([k])=>{const v=parseNum(val('gm-'+k));if(!isNaN(v)&&v>0){o[k]=+v.toFixed(1);any=true;}});
 if(!any)return toast('Cargá al menos una medida.',1);m.measures=(m.measures||[]).filter(x=>x.date!==o.date);m.measures.push(o);m.measures.sort((a,b)=>a.date.localeCompare(b.date));audit('GYM_MEDICION',gName(c)+' · '+dmy(o.date));save();gFichaOpen(c.id);toast('Medición guardada');};
A.gFreeze=el=>{const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!c||!m)return;
 modal(isNC()?'Congelar plan':'Congelar membresía',`<p class="sm">${esc(gName(c))} · paga hasta ${dmy(m.due)}. Mientras está congelada no puede ingresar, y el vencimiento se corre los días elegidos. Si vuelve antes, al descongelar se descuentan los días que no usó.</p><div class="grid g2"><div><label for="gz-d">Días</label><select id="gz-d">${[7,15,21,30,45,60].map(n=>`<option ${n===15?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="gz-r">Motivo</label><select id="gz-r"><option>Vacaciones</option><option>Lesión</option><option>Viaje</option><option>Enfermedad</option><option>Otro</option></select></div></div>`,
 {okText:'Congelar',onOk:()=>{const t=gT(),n=+val('gz-d')||15;if(m.due<t){toast('La cuota está vencida: cobrala antes de congelar.',1);return false;}m.freeze={from:t,until:addDays(t,n-1),reason:val('gz-r')};const prev=m.due;m.due=addDays(m.due,n);
  audit('GYM_CONGELAR',gName(c)+' · '+n+' días · '+m.freeze.reason,{ent:'gym',eid:c.id,old:prev,nw:m.due});save();rerender();setTimeout(()=>gFichaOpen(c.id),30);toast('Congelada hasta el '+dmy(m.freeze.until)+'. Nuevo vencimiento: '+dmy(m.due));}});};
A.gUnfreeze=el=>{const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!m||!m.freeze)return;const rem=Math.max(0,gDiff(gT(),m.freeze.until));const prev=m.due;m.due=addDays(m.due,-rem);m.freeze=null;audit('GYM_DESCONGELAR',gName(c)+' · se descontaron '+rem+' días',{ent:'gym',eid:c.id,old:prev,nw:m.due});save();rerender();setTimeout(()=>gFichaOpen(c.id),30);toast('Descongelada. Paga hasta el '+dmy(m.due));};
A.gFixDue=el=>{if(!isAdm())return;const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!m)return;
 modal('Corregir vencimiento',`<p class="sm">Para corregir un error de carga o una cuota devuelta. Queda en auditoría con el motivo. El dinero se corrige en Vender › Devoluciones.</p><label for="gfx-d">Paga hasta</label><input id="gfx-d" type="date" value="${m.due}"><label for="gfx-r">Motivo</label><input id="gfx-r" maxlength="120">`,
 {onOk:w=>{const d=val('gfx-d'),r=val('gfx-r').trim();if(!d)return w._err('Elegí la fecha.'),false;if(r.length<4)return w._err('El motivo es obligatorio.'),false;const prev=m.due;m.due=d;m.nuevo=false;audit('GYM_CORREGIR_VENCIMIENTO',gName(c)+' · '+r,{ent:'gym',eid:c.id,old:prev,nw:d,reason:r});save();rerender();setTimeout(()=>gFichaOpen(c.id),30);}});};
A.gBaja=el=>{const c=gCust(el.dataset.id),m=gm(el.dataset.id);if(!c||!m)return;const on=gActive(c);confirmBox(on?'Dar de baja':'Reactivar',on?'Deja de figurar entre los activos y no puede ingresar. El historial se conserva.':'Vuelve a figurar como activo. Cobrá la cuota si está vencida.',()=>{m.baja=on;audit(on?'GYM_BAJA':'GYM_REACTIVAR',gName(c));save();rerender();});};

/* ---------- membresías / planes y ajustes ---------- */
reg('gplanes',isNC()?'Planes':'Membresías','file','gym_admin',()=>{const A0=gActives();const C=G().cfg;
 return`<div class="row"><h1 class="sp">${GW().MM}</h1><button class="btn gold" data-act="gPlanEd" data-id="">+ ${GW().M}</button></div>
 <div class="card"><div class="tw"><table><thead><tr><th>${GW().M}</th><th class="r">Precio</th><th>Sesiones por semana</th><th>Duración</th><th class="r">${GW().SS} activos</th><th class="r">Ingreso mensual esperado</th><th></th></tr></thead><tbody>${G().plans.map(p=>{const n=A0.filter(c=>gm(c.id).plan===p.id).length;return`<tr><td><b>${esc(p.name)}</b><div class="sm mut">${esc(p.desc||'')}</div></td><td class="r">${money(gPrice(p))}</td><td>${p.weekly?p.weekly:'Libre'}</td><td>${p.days?p.days+' día(s)':'1 mes'}</td><td class="r">${n}</td><td class="r">${money(n*gPrice(p))}</td><td class="r"><button class="btn sm" data-act="gPlanEd" data-id="${p.id}">Editar</button></td></tr>`;}).join('')}</tbody>
 <tfoot><tr><th>Total</th><th></th><th></th><th></th><th class="r">${A0.length}</th><th class="r">${money(A0.reduce((a,c)=>a+gPrice(gPlanOf(gm(c.id))),0))}</th><th></th></tr></tfoot></table></div>
 <p class="sm mut">Cada ${GW().m} es un artículo de la categoría «${isNC()?'Planes de entrenamiento':'Membresías'}» en Inventario: se cobra en Vender (con caja, comprobante y ARCA) y al cobrarse extiende el vencimiento un mes desde la fecha de vencimiento (o desde hoy si venció hace más que el período de gracia). Ingreso mensual esperado = ${GW().ss} activos × precio.</p></div>
 <div class="card"><h3>Reglas de ${GW().m} y acceso</h3><div class="grid g4"><div><label for="gc-g">Período de gracia (días)</label><input id="gc-g" inputmode="numeric" value="${C.grace}"></div><div><label for="gc-a">Avisar vencimientos con (días)</label><input id="gc-a" inputmode="numeric" value="${C.alertDays}"></div><div><label for="gc-c">Aforo (personas)</label><input id="gc-c" inputmode="numeric" value="${C.capacity}"></div></div>
 <div class="grid g2"><div><label for="gc-mp">Link de pago fijo (Mercado Pago o Stripe, https)</label><input id="gc-mp" value="${esc(C.mpLink)}" placeholder="https://link.mercadopago.com.ar/…"></div><div><label for="gc-al">Alias para transferencias</label><input id="gc-al" value="${esc(C.alias)}"></div><div><label for="gc-ap">Dirección de la app del ${GW().s}</label><input id="gc-ap" value="${esc(C.appUrl)}" placeholder="${esc(gAppBase())}"></div></div>
 <p class="sm mut">El link de pago va en los avisos y en la app. El pago que llega por el link se confirma a mano cobrando la cuota en Vender con el medio «Transferencia» o «QR»: la confirmación automática por webhook necesita la cuenta del comercio y un servidor (pendiente).</p><button class="btn gold" data-act="gCfgSave">Guardar reglas</button></div>`;},null,'Gimnasio');
A.gCfgSave=()=>{const C=G().cfg,u=val('gc-mp').trim();if(u&&!/^https:\/\/([a-z0-9-]+\.)*(mercadopago\.com(\.ar)?|mpago\.la|stripe\.com|buy\.stripe\.com)(\/|$)/i.test(u))return toast('El link de pago tiene que ser https de Mercado Pago o Stripe.',1);
 const ap=val('gc-ap').trim();if(ap&&!/^https?:\/\//.test(ap))return toast('La dirección de la app tiene que empezar con https://',1);
 const old=JSON.stringify(C);C.grace=Math.min(15,Math.max(0,parseInt(val('gc-g'))||0));C.alertDays=Math.min(30,Math.max(1,parseInt(val('gc-a'))||5));C.capacity=Math.max(0,parseInt(val('gc-c'))||0);C.mpLink=u;C.alias=val('gc-al').trim().slice(0,40);C.appUrl=ap;
 audit('GYM_REGLAS','gracia '+C.grace+' d · aviso '+C.alertDays+' d · aforo '+C.capacity,{ent:'gym',old,nw:JSON.stringify(C)});save();rerender();toast('Reglas guardadas');};
A.gPlanEd=el=>{if(!can('gym_admin'))return;const p=el.dataset.id?gPlan(el.dataset.id):null;const pr=p?prod(p.pid):null;
 modal(p?'Editar '+GW().m:(isNC()?'Nuevo plan':'Nueva membresía'),`<label for="gp-n">Nombre</label><input id="gp-n" maxlength="40" value="${esc(p?p.name:'')}"><div class="grid g2"><div><label for="gp-p">Precio ($)</label>${numIn('gp-p',pr?pr.price:0)}</div><div><label for="gp-w">Sesiones por semana (0 = libre)</label><input id="gp-w" inputmode="numeric" value="${p?p.weekly:0}"></div><div><label for="gp-d">Duración</label><select id="gp-d"><option value="0">1 mes</option><option value="1" ${p&&p.days===1?'selected':''}>1 día (pase diario)</option><option value="7" ${p&&p.days===7?'selected':''}>1 semana</option></select></div>${isNC()?`<div><label for="gp-mo">Modalidad</label><select id="gp-mo"><option value="presencial">Presencial</option><option value="virtual" ${p&&p.mode==='virtual'?'selected':''}>Virtual</option></select></div>`:''}</div><label for="gp-x">Descripción (se ve en el menú público)</label><input id="gp-x" maxlength="90" value="${esc(p?p.desc:'')}">`,
 {onOk:w=>{const n=val('gp-n').trim(),price=cents(val('gp-p')),wk=parseInt(val('gp-w'))||0;if(n.length<3)return w._err('Falta el nombre.'),false;if(!(price>0))return w._err('El precio debe ser mayor a cero.'),false;if(wk<0||wk>7)return w._err('Sesiones por semana: de 0 a 7.'),false;
  const days=+val('gp-d')||0,desc=val('gp-x').trim(),mode=isNC()?val('gp-mo'):'presencial';const cat=S.rubros.find(r=>r.id==='gm-memb')?'gm-memb':S.rubros[0].id;
  if(p){const q=prod(p.pid);if(q){if(q.price!==price)audit('PRECIO',q.name+' '+money(q.price)+' → '+money(price),{ent:'producto',eid:q.id,old:q.price,nw:price});q.price=price;q.name=n;q.desc=desc;}Object.assign(p,{name:n,weekly:wk,days,desc,mode});}
  else{const id='gp'+uid();S.products.push({id:'p-'+id,name:n,sub:GW().m,grupo:'',rubro:cat,price,cost:0,stock:9999,unit:'u',barcode:'',plu:'',menu:true,active:true,desc,featured:false,noStock:true,gymPlan:id});G().plans.push({id,pid:'p-'+id,name:n,weekly:wk,days,desc,mode});audit('GYM_PLAN_ALTA',n+' · '+money(price));}
  save();if(typeof pubRefresh==='function')pubRefresh();rerender();}});};

