const gNextDate=(day,from)=>{from=from||gT();const d=dowOfKey(from);return addDays(from,(day-d+7)%7);};
reg('gclases','Clases y reservas','check','gym',()=>{const t=gT();const trs=S.employees.filter(e=>e.active);
 return`<div class="row"><h1 class="sp">Clases y reservas</h1></div><div class="g-days">${[1,2,3,4,5,6].map(d=>{const L=G().classes.filter(c=>c.day===d).sort((a,b)=>a.time.localeCompare(b.time));const nd=gNextDate(d,t);
  return`<div class="card"><h3>${GDAYS[d]} <span class="sm mut">${dmy(nd)}</span></h3>${L.map(c=>{const n=G().res.filter(r=>r.cid===c.id&&r.date===nd).length,full=n>=c.cap,tr=S.employees.find(e=>e.id===c.trainer);return`<div class="g-cls"><div class="row"><b class="sp">${esc(c.time)} · ${esc(c.name)}</b><span class="tag ${full?'bad':'ok'}">${n}/${c.cap}</span></div><div class="g-meter${full?' full':''}"><i style="width:${Math.min(100,Math.round(n/c.cap*100))}%"></i></div><div class="sm mut">${esc(tr?tr.name:'')}</div><button class="btn sm" data-act="gCls" data-id="${c.id}">Reservas y asistencia</button></div>`;}).join('')||'<p class="mut sm">Sin clases.</p>'}</div>`;}).join('')}</div>
 ${can('gym_admin')?`<div class="card"><h3>Agregar clase a la grilla</h3><div class="grid g4"><div><label for="gn-n">Clase</label><input id="gn-n" maxlength="30" placeholder="Ej: Funcional"></div><div><label for="gn-d">Día</label><select id="gn-d">${[1,2,3,4,5,6].map(d=>`<option value="${d}">${GDAYS[d]}</option>`).join('')}</select></div><div><label for="gn-t">Hora</label><input id="gn-t" type="time" value="19:00"></div><div><label for="gn-c">Cupos</label><input id="gn-c" inputmode="numeric" value="15"></div><div><label for="gn-p">Profesor</label><select id="gn-p">${trs.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div></div><button class="btn gold" data-act="gClsAdd" style="margin-top:.5rem">Agregar clase</button></div>`:''}`;},null,'Gimnasio');
A.gClsAdd=()=>{const n=val('gn-n').trim(),cap=parseInt(val('gn-c'))||0;if(n.length<3)return toast('Escribí el nombre de la clase.',1);if(cap<1)return toast('Los cupos deben ser 1 o más.',1);G().classes.push({id:uid(),name:n,day:+val('gn-d'),time:val('gn-t')||'19:00',cap,trainer:val('gn-p')});audit('GYM_CLASE_ALTA',n+' · '+GDAYS[+val('gn-d')]+' '+val('gn-t'));save();rerender();toast('Clase agregada');};
A.gCls=el=>{$$('#modal-root .ov').forEach(o=>o.remove());const c=G().classes.find(x=>x.id===el.dataset.id);if(!c)return;const nd=gNextDate(c.day),R=G().res.filter(r=>r.cid===c.id&&r.date===nd),taken=new Set(R.map(r=>r.cust)),full=R.length>=c.cap;
 const free=gActives().filter(x=>{const m=gm(x.id);return m.due>=gT()&&!gFrozen(m)&&!taken.has(x.id);}).sort((a,b)=>gName(a).localeCompare(gName(b),'es'));const done=new Set(G().catt.filter(a=>a.cid===c.id&&a.date===nd).map(a=>a.cust));
 modal(c.name+' · '+GDAYS[c.day]+' '+c.time,`<p class="sm">${dmy(nd)} · ${R.length} de ${c.cap} cupos${full?' · <b>completa</b>':''}</p><div class="tw"><table><tbody>${R.map(r=>{const x=gCust(r.cust);return`<tr><td>${esc(gName(x))}</td><td class="r">${done.has(r.cust)?'<span class="tag ok">Presente</span>':`<button class="btn sm" data-act="gClsPres" data-cid="${c.id}" data-id="${r.cust}">Presente</button>`}<button class="btn sm" data-act="gClsDel" data-id="${r.id}" data-cid="${c.id}">Liberar</button></td></tr>`;}).join('')||'<tr><td class="mut">Sin reservas.</td></tr>'}</tbody></table></div>
 <label for="gr-m">Reservar un lugar</label><div class="row"><select id="gr-m" style="flex:1">${free.slice(0,150).map(x=>`<option value="${x.id}">${esc(gName(x))}</option>`).join('')}</select><button class="btn gold" data-act="gClsRes" data-cid="${c.id}" ${full?'disabled':''}>Reservar</button></div>${can('gym_admin')?`<p style="margin-top:.8rem"><button class="btn sm" data-act="gClsRm" data-id="${c.id}">Quitar la clase de la grilla</button></p>`:''}`,{ok:false,cancelText:'Cerrar',wide:true});};
A.gClsRes=el=>{const c=G().classes.find(x=>x.id===el.dataset.cid),cid=val('gr-m');if(!c||!cid)return;const nd=gNextDate(c.day);if(G().res.filter(r=>r.cid===c.id&&r.date===nd).length>=c.cap)return toast('La clase está completa.',1);if(G().res.some(r=>r.cid===c.id&&r.date===nd&&r.cust===cid))return toast('Ya tiene lugar.',1);G().res.push({id:uid(),cid:c.id,date:nd,cust:cid});save();A.gCls({dataset:{id:c.id}});toast('Lugar reservado');};
A.gClsDel=el=>{G().res=G().res.filter(r=>r.id!==el.dataset.id);save();A.gCls({dataset:{id:el.dataset.cid}});};
A.gClsPres=el=>{const c=G().classes.find(x=>x.id===el.dataset.cid),cu=gCust(el.dataset.id);if(!c||!cu)return;const nd=gNextDate(c.day);G().catt.push({id:uid(),cid:c.id,date:nd,cust:cu.id});if(nd===gT()&&!gAttToday(cu.id))G().att.push({id:uid(),cust:cu.id,date:nd,ts:now(),method:'clase'});save();A.gCls({dataset:{id:c.id}});};
