reg('gagenda','Agenda de sesiones','check','gym',()=>{const t=gT();const A0=gActives();
 return`<div class="row"><h1 class="sp">Agenda de sesiones</h1></div><p class="sm mut">Horarios fijos de cada ${GW().s} según su plan. «Presente» registra la asistencia de la sesión de hoy.</p><div class="g-days">${[1,2,3,4,5,6].map(d=>{const L=G().slots.filter(s=>s.day===d).sort((a,b)=>a.time.localeCompare(b.time));const nd=gNextDate(d,t);
  return`<div class="card"><h3>${GDAYS[d]} <span class="sm mut">${dmy(nd)}</span></h3>${L.map(s=>{const c=gCust(s.cust);if(!c)return'';const st=gStatus(c),pres=nd===t&&gAttToday(c.id);return`<div class="g-cls"><div class="row"><b class="sp">${esc(s.time)} · ${esc(gName(c))}</b><span class="tag ${s.mode==='virtual'?'sim':''}">${s.mode==='virtual'?'Virtual':'Presencial'}</span></div><div class="sm">${gTag(st)}</div><div class="row">${nd===t?(pres?'<span class="tag ok">Presente</span>':`<button class="btn sm gold" data-act="gSlotPres" data-id="${c.id}">Presente</button>`):''}<button class="btn sm" data-act="gFicha" data-id="${c.id}">Ficha</button><button class="btn sm" data-act="gSlotDel" data-id="${s.id}">Quitar</button></div></div>`;}).join('')||'<p class="mut sm">Libre.</p>'}</div>`;}).join('')}</div>
 <div class="card"><h3>Agregar horario fijo</h3><div class="grid g4"><div><label for="ga-c">${GW().S}</label><select id="ga-c">${A0.sort((a,b)=>gName(a).localeCompare(gName(b),'es')).map(c=>`<option value="${c.id}">${esc(gName(c))}</option>`).join('')}</select></div><div><label for="ga-d">Día</label><select id="ga-d">${[1,2,3,4,5,6].map(d=>`<option value="${d}">${GDAYS[d]}</option>`).join('')}</select></div><div><label for="ga-t">Hora</label><input id="ga-t" type="time" value="18:00"></div><div><label for="ga-m">Modalidad</label><select id="ga-m"><option value="presencial">Presencial</option><option value="virtual">Virtual</option></select></div></div><button class="btn gold" data-act="gSlotAdd" style="margin-top:.5rem">Agregar</button></div>`;},null,'Gimnasio');
A.gSlotAdd=()=>{const cid=val('ga-c'),c=gCust(cid);if(!c)return;const m=gm(cid),pl=gPlanOf(m),d=+val('ga-d'),tm=val('ga-t');
 if(pl&&pl.weekly&&G().slots.filter(s=>s.cust===cid).length>=pl.weekly)return toast('Su plan es de '+pl.weekly+' sesión(es) por semana: ya tiene todos los horarios.',1);
 const clash=G().slots.find(s=>s.day===d&&Math.abs((+s.time.slice(0,2)*60+ +s.time.slice(3))-(+tm.slice(0,2)*60+ +tm.slice(3)))<45&&s.mode!=='virtual'&&val('ga-m')!=='virtual');
 if(clash)toast('Atención: se superpone con '+gName(gCust(clash.cust))+' ('+clash.time+').');G().slots.push({id:uid(),cust:cid,day:d,time:tm,mode:val('ga-m')});save();rerender();toast('Horario agregado');};
A.gSlotDel=el=>{G().slots=G().slots.filter(s=>s.id!==el.dataset.id);save();rerender();};
A.gSlotPres=el=>{const c=gCust(el.dataset.id);if(!c)return;const r=gProcess(c,'sesion');if(r.res==='denied')toast('No registrada: '+r.why,1);else toast('Asistencia registrada'+(r.warns.length?': '+r.warns[0]:''));rerender();};

/* ---------- rutinas / programas ---------- */
let gR={cust:'',draft:null,shift:0,cat:''};
A.gRtFor=el=>{$$('#modal-root .ov').forEach(o=>o.remove());gR.cust=el.dataset.id;gR.draft=null;go('grutinas');rerender();};
reg('grutinas',isNC()?'Programas':'Rutinas','list','gym_train',()=>{const act=gActives().sort((a,b)=>gName(a).localeCompare(gName(b),'es'));const sel=gCust(gR.cust)||act[0];const m=sel?gm(sel.id):null,d=gR.draft;
 const list=G().routines.filter(r=>!gR.cust||r.cust===gR.cust).sort((a,b)=>b.created.localeCompare(a.created)).slice(0,15);const EL=G().ex.filter(e=>!gR.cat||e.cat===gR.cat);
 return`<div class="row"><h1 class="sp">${isNC()?'Programas de entrenamiento':'Rutinas'}</h1><span class="tag">${G().ex.length} ejercicios · ${G().mq.filter(q=>q.state==='ok').length} ${isNC()?'equipos':'máquinas'} operativos</span></div>
 <div class="card"><h3>Entrenador inteligente</h3><p class="sm mut">Arma la ${isNC()?'programación':'rutina'} con reglas de entrenamiento según el objetivo, el nivel, las lesiones, ${isNC()?'el equipamiento disponible y la modalidad':'las máquinas que funcionan'} y la evolución de las mediciones. El profesor la revisa, ajusta las cargas y la asigna.</p>
 ${sel?`<div class="grid g4"><div><label for="gg-c">${GW().S}</label><select id="gg-c">${act.map(c=>`<option value="${c.id}" ${c.id===sel.id?'selected':''}>${esc(gName(c))}</option>`).join('')}</select></div><div><label for="gg-g">Objetivo</label><select id="gg-g">${Object.entries(GGOALS).map(([k,l])=>`<option value="${k}" ${m.goal===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="gg-l">Nivel</label><select id="gg-l">${Object.entries(GLEVELS).map(([k,l])=>`<option value="${k}" ${m.level===k?'selected':''}>${l}</option>`).join('')}</select></div><div><label for="gg-d">Días por semana</label><select id="gg-d">${[2,3,4,5].map(n=>`<option ${((gPlanOf(m)||{}).weekly||3)===n?'selected':''}>${n}</option>`).join('')}</select></div></div>
 <div class="row">${Object.entries(GINJ).map(([k,l])=>`<label class="chk"><input type="checkbox" class="gg-i" value="${k}" ${(m.inj||[]).includes(k)?'checked':''}> Cuidar ${l.toLowerCase()}</label>`).join('')}${isNC()?`<label class="chk"><input type="checkbox" id="gg-h" ${m.mode==='virtual'?'checked':''}> Entrena en casa (virtual)</label>`:''}</div>${m.health?`<p class="sm">Salud según la ficha: ${esc(m.health)}</p>`:''}
 <div class="row"><button class="btn gold" data-act="gRtGen">Generar</button>${d?'<button class="btn" data-act="gRtVar">Otra variante</button>':''}</div>`:`<p class="mut">Cargá ${GW().ss} para armar ${isNC()?'programas':'rutinas'}.</p>`}
 ${d?`<div class="card" style="margin-top:.8rem"><div class="row"><div class="sp"><b>${esc(d.name)}</b><div class="sm mut">Propuesta para ${esc(gName(gCust(d.cust)))} · ${esc(GLEVELS[d.level])}</div></div><button class="btn gold" data-act="gRtSave">Asignar</button><button class="btn" data-act="gRtDrop">Descartar</button></div><ul class="sm">${d.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>${gRtTable(d)}</div>`:''}</div>
 <div class="card"><div class="row"><h3 class="sp">Asignadas</h3><div><label for="gg-f">Ver de</label><select id="gg-f"><option value="">Todos</option>${act.map(c=>`<option value="${c.id}" ${gR.cust===c.id?'selected':''}>${esc(gName(c))}</option>`).join('')}</select></div></div>
 ${list.map(r=>{const c=gCust(r.cust);return`<div class="card"><div class="row"><div class="sp"><b>${esc(r.name)}</b><div class="sm mut">${esc(gName(c))} · ${esc(GLEVELS[r.level]||'')} · ${dmy(r.created)} · ${esc(r.by||'')}${r.auto?' · entrenador inteligente':''}</div></div><button class="btn sm" data-act="gRtEdit" data-id="${r.id}">Editar cargas</button>${c?gWaBtn(c,'rutina','WhatsApp'):''}<button class="btn sm" data-act="gRtDel" data-id="${r.id}">Eliminar</button></div>${gRtTable(r)}</div>`;}).join('')||'<p class="mut">Todavía no hay asignadas.</p>'}</div>
 <div class="card"><h3>Catálogo de ejercicios</h3><div class="row" role="group" aria-label="Grupo">${[['','Todos']].concat(Object.entries(GEXCAT)).map(([k,l])=>`<button class="btn sm ${gR.cat===k?'on':''}" data-act="gExCat" data-c="${k}">${l}</button>`).join('')}</div>
 <div class="tw"><table><thead><tr><th>Ejercicio</th><th>Grupo</th><th>${isNC()?'Equipo':'Máquina'}</th><th>Evitar con</th><th>Indicación</th><th></th></tr></thead><tbody>${EL.map(e=>{const q=e.mach.map(gMq).filter(Boolean),ok=!q.length||q.some(x=>x.state==='ok');return`<tr><td><b>${esc(e.name)}</b></td><td>${esc(GEXCAT[e.cat])}</td><td>${q.length?esc(q.map(x=>x.name).join(' / '))+(ok?'':' <span class="tag bad">en reparación</span>'):'<span class="mut">Peso corporal</span>'}</td><td>${e.avoid.map(a=>GINJ[a]).join(', ')||'—'}</td><td class="sm">${esc(e.tip)}</td><td class="r"><button class="btn sm" data-act="gVideo" data-k="ex" data-id="${e.id}">${gYtId(e.video)?'▶ Video':'Video'}</button></td></tr>`;}).join('')}</tbody></table></div></div>`;},
 ()=>{const f=$('#gg-f');f&&f.addEventListener('change',()=>{gR.cust=f.value;rerender();});const c=$('#gg-c');c&&c.addEventListener('change',()=>{gR.cust=c.value;gR.draft=null;rerender();});},'Gimnasio');
A.gExCat=el=>{gR.cat=el.dataset.c;rerender();};
function gRtOpts(){const cid=val('gg-c'),c=gCust(cid),m=gm(cid);return{cust:cid,o:{goal:val('gg-g'),level:val('gg-l'),days:+val('gg-d'),inj:$$('.gg-i').filter(x=>x.checked).map(x=>x.value),home:!!($('#gg-h')&&$('#gg-h').checked),trend:m?gTrend(m):'',shift:0},c,m};}
A.gRtGen=()=>{const R=gRtOpts();if(!R.c)return;R.m.goal=R.o.goal;R.m.level=R.o.level;R.m.inj=R.o.inj;gR.shift=0;gR.cust=R.cust;gR.draft=Object.assign({cust:R.cust,opts:R.o},gymGenRoutine(R.o,G().ex,G().mq));save();rerender();};
A.gRtVar=()=>{const d=gR.draft;if(!d)return;gR.shift++;d.opts.shift=gR.shift;gR.draft=Object.assign({cust:d.cust,opts:d.opts},gymGenRoutine(d.opts,G().ex,G().mq));rerender();};
A.gRtDrop=()=>{gR.draft=null;rerender();};
A.gRtSave=()=>{const d=gR.draft,c=d&&gCust(d.cust);if(!c)return;G().routines.push({id:uid(),cust:c.id,created:gT(),by:user?user.name:'',auto:true,name:d.name,goal:d.goal,level:d.level,days:d.days,notes:d.notes});audit('GYM_RUTINA',gName(c)+' · '+d.name);gR.draft=null;save();rerender();toast('Asignada. Enviale la app desde la ficha para que la vea en el celular.');};
A.gRtDel=el=>{const r=G().routines.find(x=>x.id===el.dataset.id);if(!r)return;confirmBox('Eliminar','Se elimina «'+esc(r.name)+'».',()=>{G().routines=G().routines.filter(x=>x.id!==r.id);audit('GYM_RUTINA_BAJA',r.name);save();rerender();});};
A.gRtEdit=el=>{$$('#modal-root .ov').forEach(o=>o.remove());const r=G().routines.find(x=>x.id===el.dataset.id);if(!r)return;const EXO=G().ex.slice().sort((a,b)=>a.cat.localeCompare(b.cat)||a.name.localeCompare(b.name,'es'));
 modal('Editar '+r.name,`<label for="gre-n">Nombre</label><input id="gre-n" value="${esc(r.name)}" maxlength="60">${r.days.map((d,di)=>`<h4 style="margin:.8rem 0 .3rem">${esc(d.n)}</h4>${d.items.map((it,ii)=>{const e=gEx(it.ex),k=di+'_'+ii;return`<div class="grid g4" style="align-items:end"><div><b>${esc(e?e.name:'')}</b></div><div><label for="gre-s${k}">Series</label><input id="gre-s${k}" inputmode="numeric" value="${it.s}"></div><div><label for="gre-r${k}">Reps</label><input id="gre-r${k}" value="${esc(it.r)}"></div><div><label for="gre-k${k}">Kg</label><input id="gre-k${k}" inputmode="decimal" value="${esc(it.kg)}"></div><label class="chk"><input type="checkbox" id="gre-x${k}"> Quitar</label></div>`;}).join('')}<label for="gre-a${di}">Agregar ejercicio</label><select id="gre-a${di}"><option value="">—</option>${EXO.map(e=>`<option value="${e.id}">${esc(GEXCAT[e.cat]+' · '+e.name)}</option>`).join('')}</select>`).join('')}`,
 {wide:true,okText:'Guardar',onOk:()=>{r.name=val('gre-n').trim()||r.name;r.days.forEach((d,di)=>{d.items=d.items.map((it,ii)=>{const k=di+'_'+ii;if($('#gre-x'+k).checked)return null;return Object.assign(it,{s:Math.max(1,parseInt(val('gre-s'+k))||it.s),r:val('gre-r'+k).trim()||it.r,kg:val('gre-k'+k).trim()});}).filter(Boolean);
  const add=val('gre-a'+di);if(add){const P=GRT_PRM[r.goal]||GRT_PRM.salud,lv=Math.max(0,['principiante','intermedio','avanzado'].indexOf(r.level));d.items.push({ex:add,s:P.s[lv],r:P.r,kg:'',rest:P.rest});}});r.auto=false;audit('GYM_RUTINA_EDIT',r.name);save();rerender();toast('Guardado');}});};

/* ---------- máquinas / equipamiento ---------- */
reg('gmaq',isNC()?'Equipamiento':'Máquinas y mantenimiento','gear','gym_train',()=>{const t=gT(),L=G().mq.slice().sort((a,b)=>(a.state==='ok'?1:0)-(b.state==='ok'?1:0)||gNext(a).localeCompare(gNext(b)));const rep=L.filter(q=>q.state!=='ok'),over=L.filter(q=>q.state==='ok'&&gNext(q)<t),soon=L.filter(q=>q.state==='ok'&&gNext(q)>=t&&gNext(q)<=addDays(t,15));
 return`<div class="row"><h1 class="sp">${isNC()?'Equipamiento':'Máquinas y mantenimiento'}</h1><button class="btn gold" data-act="gMqEd" data-id="">+ ${isNC()?'Equipo':'Máquina'}</button></div>
 <div class="grid g4"><div class="card kpi"><span>Equipos</span><b>${L.length}</b><span>registrados</span></div><div class="card kpi"><span>En reparación</span><b>${rep.length}</b><span>quedan fuera de las rutinas nuevas</span></div><div class="card kpi"><span>Mantenimiento vencido</span><b>${over.length}</b><span>${soon.length} más en 15 días</span></div></div>
 <div class="card"><p class="sm mut">Pegá el QR en cada ${isNC()?'equipo':'máquina'}: el ${GW().s} lo escanea y ve el video de cómo usarla.</p><div class="tw"><table><thead><tr><th>${isNC()?'Equipo':'Máquina'}</th><th>Estado</th><th>Último mantenimiento</th><th>Próximo</th><th class="r"></th></tr></thead><tbody>${L.map(q=>{const nx=gNext(q);const st=q.state!=='ok'?'<span class="tag bad">En reparación</span>':nx<t?'<span class="tag bad">Mantenimiento vencido</span>':nx<=addDays(t,15)?`<span class="tag warn">En ${gDiff(t,nx)} días</span>`:'<span class="tag ok">Operativa</span>';
  return`<tr><td><b>${esc(q.name)}</b><div class="sm mut">${esc(q.zone)}${q.notes?' · '+esc(q.notes):''}</div></td><td>${st}</td><td>${dmy(q.last)}</td><td>${dmy(nx)} <span class="sm mut">(cada ${q.every} d)</span></td><td class="r"><button class="btn sm" data-act="gMqMt" data-id="${q.id}">Registrar mantenimiento</button><button class="btn sm" data-act="gMqSt" data-id="${q.id}">${q.state==='ok'?'En reparación':'Operativa'}</button><button class="btn sm" data-act="gVideo" data-k="mq" data-id="${q.id}">${gYtId(q.video)?'▶ Video':'Video'}</button><button class="btn sm" data-act="gMqQr" data-id="${q.id}">QR</button><button class="btn sm" data-act="gMqEd" data-id="${q.id}">Editar</button></td></tr>`;}).join('')}</tbody></table></div></div>`;},null,'Gimnasio');
A.gMqSt=el=>{const q=gMq(el.dataset.id);if(!q)return;q.state=q.state==='ok'?'rep':'ok';if(q.state==='ok')q.notes='';audit(q.state==='ok'?'GYM_EQUIPO_OPERATIVO':'GYM_EQUIPO_REPARACION',q.name);save();rerender();};
A.gMqQr=el=>{const q=gMq(el.dataset.id);if(!q)return;const u=q.video||gYt('cómo usar '+q.name);modal('QR de '+q.name,`<div style="width:240px;height:240px;margin:0 auto;background:#fff;padding:8px;border-radius:10px">${QR.svg(u,4,2)}</div><p class="sm mut" style="text-align:center">Imprimilo y pegalo en el equipo: abre el video de uso.</p>`,{ok:false,cancelText:'Cerrar'});};
A.gMqMt=el=>{const q=gMq(el.dataset.id);if(!q)return;modal('Mantenimiento · '+q.name,`<div class="grid g2"><div><label for="gmt-d">Fecha</label><input id="gmt-d" type="date" value="${gT()}"></div><div><label for="gmt-c">Costo ($, opcional)</label>${numIn('gmt-c',0)}</div></div><label for="gmt-t">Qué se hizo</label><input id="gmt-t" maxlength="120"><label class="chk"><input type="checkbox" id="gmt-ok" checked> Queda operativa</label>
 ${q.log.length?`<h4>Historial</h4><div class="tw"><table><tbody>${q.log.slice().reverse().slice(0,8).map(l=>`<tr><td>${dmy(l.date)}</td><td>${esc(l.txt)}</td><td class="r">${l.cost?money(l.cost):''}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="sm mut">Si el gasto se paga desde la caja, registralo también como egreso en Gestión de caja.</p>`,
 {onOk:w=>{const d=val('gmt-d'),tx=val('gmt-t').trim(),c=cents(val('gmt-c')||'0');if(!d||tx.length<3)return w._err('Completá fecha y detalle.'),false;q.log.push({date:d,txt:tx,cost:isNaN(c)?0:c});if(d>q.last)q.last=d;if($('#gmt-ok',w).checked){q.state='ok';q.notes='';}audit('GYM_MANTENIMIENTO',q.name+' · '+tx+(c>0?' · '+money(c):''));save();rerender();toast('Próximo mantenimiento: '+dmy(gNext(q)));}});};
A.gMqEd=el=>{const q=el.dataset.id?gMq(el.dataset.id):null;modal(q?'Editar':'Nuevo equipo',`<label for="gq-n">Nombre</label><input id="gq-n" maxlength="50" value="${esc(q?q.name:'')}"><div class="grid g2"><div><label for="gq-z">Zona</label><input id="gq-z" maxlength="30" value="${esc(q?q.zone:'')}"></div><div><label for="gq-e">Mantenimiento cada (días)</label><input id="gq-e" inputmode="numeric" value="${q?q.every:90}"></div><div><label for="gq-l">Último mantenimiento</label><input id="gq-l" type="date" value="${q?q.last:gT()}"></div></div><label for="gq-v">Video de uso (YouTube, opcional)</label><input id="gq-v" value="${esc(q?q.video:'')}" placeholder="https://www.youtube.com/…"><label for="gq-o">Notas</label><input id="gq-o" maxlength="120" value="${esc(q?q.notes:'')}">${q?'<p style="margin-top:.6rem"><button class="btn sm" data-act="gMqDel" data-id="'+q.id+'">Eliminar equipo</button></p>':''}`,
 {onOk:w=>{const n=val('gq-n').trim(),v=val('gq-v').trim();if(n.length<3)return w._err('Falta el nombre.'),false;if(!gYtOk(v))return w._err('Tiene que ser un enlace de un video de YouTube (youtube.com/watch?v=… o youtu.be/…).'),false;
  const d={name:n,zone:val('gq-z').trim(),every:Math.max(7,parseInt(val('gq-e'))||90),last:val('gq-l')||gT(),video:v,notes:val('gq-o').trim()};if(q)Object.assign(q,d);else G().mq.push(Object.assign({id:'mq'+uid(),state:'ok',log:[]},d));audit('GYM_EQUIPO',n);save();rerender();}});};
A.gMqDel=el=>{const q=gMq(el.dataset.id);if(!q)return;$$('#modal-root .ov').forEach(o=>o.remove());confirmBox('Eliminar equipo','Se elimina '+esc(q.name)+'. Los ejercicios que lo usaban quedan como peso corporal.',()=>{G().mq=G().mq.filter(x=>x.id!==q.id);G().ex.forEach(e=>{e.mach=e.mach.filter(x=>x!==q.id);});audit('GYM_EQUIPO_BAJA',q.name);save();rerender();});};


/* ---------- V27.2 · Inicio del gimnasio / del entrenador (diseño deportivo: héroe, anillos, plan del día) ---------- */
function gRing(p,lbl,sz){p=Math.max(0,Math.min(100,Math.round(p||0)));sz=sz||64;const r=sz/2-6,c=2*Math.PI*r;return`<svg class="g-ring" width="${sz}" height="${sz}" viewBox="0 0 ${sz} ${sz}" role="img" aria-label="${esc(lbl||p+' %')}"><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="currentColor" stroke-opacity=".14" stroke-width="7"/><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="var(--gold)" stroke-width="7" stroke-linecap="round" stroke-dasharray="${(c*p/100).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 ${sz/2} ${sz/2})"/><text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle" font-size="${sz>90?22:13}" font-weight="700" fill="currentColor">${esc(lbl||p+'%')}</text></svg>`;}
