const gIco=(n,cls)=>`<span class="g-ico ${cls||''}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="${G_ICO[n]||G_ICO.bolt}"/></svg></span>`;
