 bici:`<circle cx="60" cy="96" r="22" stroke="${A}" stroke-width="7" fill="none"/><circle cx="140" cy="96" r="22" stroke="${A}" stroke-width="7" fill="none"/><path d="M60 96l26-34h30l24 34M86 62l20 34h-46M112 52h14" stroke="#fff" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" fill="none" opacity=".85"/>`,
